;s:6:\"source\";s:6:\"Google\";}i:3;a:6:{s:6:\"author\";s:21:\"Xenia Arianna Orduela\";s:6:\"avatar\";s:118:\"https://lh3.googleusercontent.com/a-/ALV-UjXUes90uJwMhoeNC0_HxsKccoWu5c0zOT_TpS2WJUU9jSBpQ9o=s128-c0x00000000-cc-rp-mo\";s:6:\"rating\";i:5;s:4:\"text\";s:91:\"The owners are very accommodating and kind. The place is quiet. You will really find peace.\";s:9:\"timestamp\";s:27:\"2025-05-24T18:27:20.740409Z\";s:6:\"source\";s:6:\"Google\";}i:4;a:6:{s:6:\"author\";s:16:\"Khalfan Punsalan\";s:6:\"avatar\";s:121:\"https://lh3.googleusercontent.com/a-/ALV-UjXa0VigBYWVSnel9srozX3IT3Cny1IziS24PpVsxrJY_ht6XQ5LQw=s128-c0x00000000-cc-rp-mo\";s:6:\"rating\";i:5;s:4:\"text\";s:0:\"\";s:9:\"timestamp\";s:27:\"2025-03-30T22:31:28.569122Z\";s:6:\"source\";s:6:\"Google\";}}s:17:\"editorial_summary\";N;s:6:\"source\";s:6:\"google\";}i:11;a:15:{s:2:\"id\";s:27:\"ChIJrxMbPCOjkTMRA15Ed28P54A\";s:4:\"name\";s:18:\"Sadjatan Viewpoint\";s:3:\"lat\";d:16.4764017;s:3:\"lng\";d:120.56095810000001;s:7:\"address\";s:43:\"FHG6+H98, La Trinidad, Benguet, Philippines\";s:8:\"category\";s:12:\"google_place\";s:4:\"type\";s:3:\"poi\";s:6:\"rating\";d:4.7;s:18:\"user_ratings_total\";i:33;s:7:\"reviews\";i:33;s:15:\"photo_reference\";s:476:\"places/ChIJrxMbPCOjkTMRA15Ed28P54A/photos/AVoNoXQkCXleVZZJoOXlNiJFIaGxysUMja_E-uO0dKtugGEokmrFJZgRPHldrf5BgkYYarEBcTTlJOYnIwUihW9ivDF2hHumSiJ7zxH7xdU9M6lOKa-l2A2KlABZE0MyZ5ItVgITX6zHoHNOJIaCuREFv0pZdJvoHhhAzAPj2ll9qF1ntgtiWzamBGZhW_Gr9pIwwW51Ut9tdGvu30a0APggvm1wA_ejoXE4kE-AVrUh4q5Zdm9keY070zcKNngA6UNBqfFa0Sq83v1QHmSOxDJjtinlWA9FUTYNXT50GjVFeOz-xcjRzuaIk986-MlOEVN3j1S3EsVMDmyDQbB9CM_oZdinzrDRbkWbFPHlEdRMwYxHzSgsq_915Q-iORW0pMmomiVAaiWxwMz-nLwwzAOSlsVQ8TXBIPaYDAmnRe9JgMSHBA\";s:16:\"photo_references\";a:6:{i:0;s:476:\"places/ChIJrxMbPCOjkTMRA15Ed28P54A/photos/AVoNoXQkCXleVZZJoOXlNiJFIaGxysUMja_E-uO0dKtugGEokmrFJZgRPHldrf5BgkYYarEBcTTlJOYnIwUihW9ivDF2hHumSiJ7zxH7xdU9M6lOKa-l2A2KlABZE0MyZ5ItVgITX6zHoHNOJIaCuREFv0pZdJvoHhhAzAPj2ll9qF1ntgtiWzamBGZhW_Gr9pIwwW51Ut